From Coq Require Import List String.
From Buri Require Import Wire Native.
Import ListNotations Native.Native.
Open Scope string_scope.
Definition eq1_kernel_text_0 : string := "".
Definition eq1_kernel_text_1 : string := "".
Definition eq1_kernel_text_2 : string := "".
Definition eq1_kernel_text_3 : string := "".
Definition eq1_kernel_text_4 : string := "".
Definition eq1_kernel_text_5 : string := "".
Definition eq1_kernel_text_6 : string := "".
Definition eq1_kernel_text_7 : string := "".
Definition eq1_kernel_text : string := (eq1_kernel_text_0 ++ eq1_kernel_text_1 ++ eq1_kernel_text_2 ++ eq1_kernel_text_3 ++ eq1_kernel_text_4 ++ eq1_kernel_text_5 ++ eq1_kernel_text_6 ++ eq1_kernel_text_7)%string.
Definition eq1_kernel_nodes :=
 match Wire.decode_text eq1_kernel_text with
 | Some (Wire.Cons (Wire.Atom false "buri-constructor-native-1") (Wire.Cons tagged Wire.Nil)) =>
   match untag 500 tagged with Some root => elements root | _ => None end
 | _ => None end.
Definition eq1_kernel_decode := match eq1_kernel_nodes with
 | Some xs => definitions 500 (firstn 22 (skipn 0 xs)) | None => None end.
Definition eq1_kernel_program := Eval vm_compute in
 match eq1_kernel_decode with Some ds => ds | None => [] end.
Theorem eq1_kernel_exact : eq1_kernel_decode = Some eq1_kernel_program.
Proof. vm_compute. reflexivity. Qed.
Theorem eq1_kernel_names : map fst eq1_kernel_program = ["kl:buri.check-bundle";"kl:buri.bundle-h";"kl:buri.bundle-next";"kl:buri.goal?";"kl:buri.check-theorem";"kl:buri.check-cases";"kl:buri.fresh?";"kl:buri.zip";"kl:buri.zip-h";"kl:buri.variables";"kl:buri.check-case-bound";"kl:buri.induction-hyps";"kl:buri.check-steps";"kl:buri.resolve";"kl:buri.instantiate";"kl:buri.check-step-result";"kl:buri.after-rewrite";"kl:buri.replace";"kl:buri.replace-arg";"kl:buri.replace-head";"kl:buri.replace-tail";"kl:buri.replace-app"].
Proof. vm_compute. reflexivity. Qed.
Theorem eq1_kernel_complete : match eq1_kernel_nodes with
 | Some xs => List.length xs = 22 | None => False end.
Proof. vm_compute; reflexivity. Qed.
Global Opaque eq1_kernel_text_0 eq1_kernel_text_1 eq1_kernel_text_2 eq1_kernel_text_3 eq1_kernel_text_4 eq1_kernel_text_5 eq1_kernel_text_6 eq1_kernel_text_7 eq1_kernel_text eq1_kernel_nodes eq1_kernel_decode.
